import openpyxl, os, sys
path='/root/output/result.xlsx'
wb=openpyxl.load_workbook(path, data_only=False)
ws=wb['Task']
print('exists:', os.path.exists(path), 'size:', os.path.getsize(path))
print('sheets:', wb.sheetnames)
for cell in ['H12','I17','H35','L40','H42','H43','H44','H45','H46','H47','H50','L50']:
    print(cell, ws[cell].value)

# Contract checks over all written ranges.
errors=[]
for row in list(range(12,18))+list(range(19,25))+list(range(26,32))+list(range(35,41))+list(range(42,48))+[50]:
    for col in range(8,13):
        v=ws.cell(row=row, column=col).value
        if not (isinstance(v,str) and v.startswith('=')):
            errors.append(f'{ws.cell(row=row,column=col).coordinate} not formula: {v!r}')
        if isinstance(v,str) and ('PERCENTILE.INC' in v or 'PERCENTILE.EXC' in v):
            errors.append(f'{ws.cell(row=row,column=col).coordinate} has nonstandard percentile: {v}')
if wb.sheetnames != ['Task','Data']:
    errors.append(f'unexpected sheets: {wb.sheetnames!r}')
if errors:
    print('VALIDATION_ERRORS')
    print('\n'.join(errors))
    sys.exit(1)
print('validation: OK')
